PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?result WHERE {
  ?result a pv:Agent ;
           pv:areaOfExpertise pv:ProductCategory-Sensor .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT DISTINCT ?result WHERE {
  ?product a pv:Product ; pv:compatibleProduct pv:Product-COMPENSATOR .
  ?product pv:hasSupplier ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?result WHERE {
  ?service a pv:Service ;
           pv:price ?price ;
           pv:eligibleFor ?product .
  ?price pv:amount ?amount ;
         pv:currency ?currency .
  ?product pv:hasProductManager ?manager .
  FILTER(?amount = (SELECT MAX(?amount) WHERE {
    ?service2 a pv:Service ;
             pv:price ?price2 ;
             pv:eligibleFor ?product2 .
    ?price2 pv:amount ?amount2 ;
             pv:currency ?currency2 .
    FILTER(?amount2 = ?amount)
  }))
  BIND(?manager AS ?result)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?result WHERE {
  pv:U990LCDInductor pv:compatibleProduct ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?supplierName ?country ?priceAmount WHERE {
  ?product a pv:Hardware ;
    pv:price ?price ;
    pv:hasSupplier ?supplier .
  ?supplier pv:name ?supplierName ;
    pv:country ?country .
  ?price pv:amount ?priceAmount ;
    pv:currency "EUR" .
  ?product pv:price ?price .
} ORDER BY DESC(?priceAmount) LIMIT 5 OFFSET 5

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?product ?compatibleProduct ?priceDifference WHERE {
  ?product a pv:Product ;
            pv:compatibleProduct ?compatibleProduct ;
            pv:price ?price1 .
  ?compatibleProduct pv:price ?price2 .
  BIND((?price1 - ?price2) AS ?priceDifference)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?name ?email ?phone ?department ?directReport WHERE {
  ?employee a pv:Employee ;
             pv:name ?name ;
             pv:email ?email ;
             pv:phone ?phone ;
             pv:memberOf ?department ;
             pv:hasDirectReport ?directReport .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?bom (AVG(?price) AS ?averageCost) WHERE {
  ?bom a pv:BillOfMaterial ;
        pv:hasBomPart ?bomPart .
  ?bomPart pv:hasPart ?hardware ;
           pv:quantity ?quantity .
  ?hardware pv:price ?price .
  ?price pv:amount ?amount ;
         pv:currency ?currency .
  FILTER(?currency = "EUR")
  BIND(?amount / ?quantity AS ?unitCost)
} GROUP BY ?bom ORDER BY DESC(?averageCost) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT ?supplier (AVG(?reliabilityIndex) AS ?averageReliability) WHERE {
  ?product pv:hasSupplier ?supplier ;
            a pv:Hardware ;
            pv:reliabilityIndex ?reliabilityIndex .
} GROUP BY ?supplier ORDER BY DESC(?averageReliability) LIMIT 5

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT DISTINCT ?bom WHERE {
  ?bom a pv:BillOfMaterial ;
        pv:hasBomPart ?bomPart ;
        pv:hasSupplier ?supplier .
  ?bomPart pv:hasPart ?product .
  ?supplier pv:country "Poland" .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
SELECT (COUNT(DISTINCT ?supplier) AS ?result) WHERE {
  ?product pv:compatibleProduct pv:product-K367-Strain-Encoder ;
           pv:hasSupplier ?supplier .
}

